// Fills <span data-r="phase1.P_open_world_eig.cw_withheld" data-fmt="pct">
// from window.RESULTS (generated by research/figures/export_site_results.py),
// and word-counts each abstract against its venue limit (data-limit).
(function(){
  var R = window.RESULTS || {};
  function get(path){
    return path.split('.').reduce(function(o,k){ return (o==null) ? null : o[k]; }, R);
  }
  document.querySelectorAll('[data-r]').forEach(function(el){
    var v = get(el.getAttribute('data-r'));
    var fmt = el.getAttribute('data-fmt');
    if (v == null){ el.textContent = 'not run'; el.className = 'pending'; return; }
    if (fmt === 'pct') v = (100*v).toFixed(1) + '%';
    else if (fmt === 'f3') v = Number(v).toFixed(3);
    el.textContent = v;
    el.classList.add('r');
  });
  document.querySelectorAll('.abstract').forEach(function(box){
    var text = Array.prototype.map.call(box.querySelectorAll('p'), function(p){ return p.textContent; }).join(' ');
    var n = (text.trim().match(/\S+/g) || []).length;
    var lim = box.getAttribute('data-limit');
    var out = box.nextElementSibling;
    if (!out || !out.classList.contains('wc')) return;
    out.textContent = n + ' words' + (lim
      ? ' · venue limit ' + lim + (n > +lim ? ' · OVER LIMIT' : ' · within limit')
      : ' · no stated limit; check the submission form');
  });
})();
